// AJOUTÉ (2026-10-14) - nom réécrit à chaque affichage (langue changée entre-temps dans les Paramètres), cartouche
// réajusté à sa nouvelle longueur.
private void ApplyName()
{
    SkillTreeData.NodeData data = SkillTreeData.Get(_nodeId);
    if (data == null || _nameLabel == null) return;
    string name = Loc.T(data.displayName);
    if (_nameLabel.text == name) return;
    _nameLabel.text = name;
    if (_plate != null)
    {
        float w = _nameLabel.GetPreferredValues(name).x + 24f;
        _plate.sizeDelta = new Vector2(Mathf.Max(_isUnique ? 72f : 80f, w), _plate.sizeDelta.y);
    }
}

private void HandleClick()
{

Assets/Game/Scripts/UI/SkillTreeUI.cs:
    if (_debugResetButton != null) _debugResetButton.SetActive(Debug.isDebugBuild);

    RefreshAllNodes();
    Loc.Changed += OnLanguageChanged;
}

// AJOUTÉ (2026-10-14) - changement de langue : la fiche ouverte est refermée (elle serait dans l'ancienne langue) et
// les textes de l'onglet (consigne, légendes) sont réécrits.
private void OnLanguageChanged()
{
    if (this == null) { Loc.Changed -= OnLanguageChanged; return; }
    if (_isPanelOpen) ClosePanel();
    RefreshAllNodes();
}

private void OnDestroy() => Loc.Changed -= OnLanguageChanged;
